class Node:
    def __init__(self, val):
        self.val = val
        self.next = None
a = Node(1); b = Node(2)
a.next = b
n = a
while n:
    print(n.val)
    n = n.next

slow = fast = head
while fast and fast.next:
    slow = slow.next
    fast = fast.next.next
    if slow is fast:
        print('cycle')
        break
else:
    print('no cycle')
